(function(){
  function parse(text){
    var lines=String(text||'').split(/\r?\n/).map(function(s){return s.trim();}).filter(function(s){return s;});
    var rows=[];
    for(var i=0;i<lines.length;i++){
      var p=lines[i].split(/\s+/);
      if(p.length<2) continue;
      rows.push({pid:p[0], name:p[1], cpu:parseFloat(p[2])||0, mem:parseFloat(p[3])||0});
    }
    return rows;
  }
  function sortBy(rows, key){
    var c=rows.slice();
    c.sort(function(a,b){ return (b[key]||0)-(a[key]||0); });
    return c;
  }
  function analyze(text){
    var rows=parse(text), cpu=0, mem=0;
    rows.forEach(function(r){ cpu+=r.cpu; mem+=r.mem; });
    return {value:{rows:rows, totalCpu:cpu, totalMem:mem}};
  }
  var API={analyze:analyze, parse:parse, sortBy:sortBy};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__ProcsForge__=API;
})();
